from copy import deepcopy


_FIELDS = ("id", "name", "collector", "notes", "habitat", "year")


def query_specimens(records, text="", habitat=None, page=1, page_size=4):
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError("page must be a positive integer")
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError("page_size must be a positive integer")
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    needle = text.casefold()
    selected = []
    seen = set()
    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in _FIELDS):
            raise ValueError("malformed record")
        if not isinstance(record["year"], int) or isinstance(record["year"], bool):
            raise ValueError("malformed year")
        try:
            duplicate = record["id"] in seen
        except TypeError as exc:
            raise ValueError("id must be hashable") from exc
        fields = (record["name"], record["collector"], record["notes"])
        if any(not isinstance(value, str) for value in fields):
            raise ValueError("search fields must be strings")
        matches = needle in "\n".join(fields).casefold()
        if matches and (habitat is None or record["habitat"] == habitat) and not duplicate:
            seen.add(record["id"])
            selected.append(record)

    selected.sort(key=lambda item: (item["year"], str(item["id"])))
    total = len(selected)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    return {"items": deepcopy(selected[start:start + page_size]), "total": total, "pages": pages}

